input.sparql:
SELECT ?zonePower ?buildingPower WHERE {
  ?zonePower a brick:Electric_Power;
    rdfs:subClassOf+ brick:Zone;
    ref:hasExternalReference/ref:hasTimeseriesId ?zonePowerId.
  ?buildingPower a brick:Electric_Power;
    rdfs:subClassOf+ brick:Building;
    ref:hasExternalReference/ref:hasTimeseriesId ?buildingPowerId.
}
